// (i) SLL Insert Beginning & End
void insertBeginning(struct Node** head, int val) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = val;
    newNode->next = *head;
    *head = newNode;
}
void insertEnd(struct Node** head, int val) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = val; newNode->next = NULL;
    if (*head == NULL) { *head = newNode; return; }
    struct Node* temp = *head;
    while (temp->next != NULL) temp = temp->next;
    temp->next = newNode;
}

// (ii) DLL Delete by Value
void deleteNodeDLL(struct DNode** head, int key) {
    struct DNode* curr = *head;
    while (curr != NULL && curr->data != key) curr = curr->next;
    if (curr == NULL) return; // Key not found
    if (curr->prev != NULL) curr->prev->next = curr->next;
    else *head = curr->next;
    if (curr->next != NULL) curr->next->prev = curr->prev;
    free(curr);
}

// (iii) SLL Reverse (3-Pointer)
struct Node* reverseSLL(struct Node* head) {
    struct Node *prev = NULL, *curr = head, *next = NULL;
    while (curr != NULL) {
        next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }
    return prev;
}
```

